const items = $input.all();
const out = [];
const KEYWORDS = ['data', 'donnée', 'gouvernance', 'qualité', 'système d\'information', 'ia', 'intelligence artificielle'];

for (const item of items) {
  const rec = item.json.record?.fields || item.json;
  const objet = (rec.objet || rec.object_marche || '').toLowerCase();
  if (!KEYWORDS.some(k => objet.includes(k))) continue;

  out.push({
    json: {
      organisation: rec.nomacheteur || rec.acheteur_nom || 'Organisme inconnu',
      secteur: 'Secteur public',
      source: 'boamp',
      offre: 'Audit Data Flash',
      valeur_estimee: null,
      currency: 'EUR',
      contact_name: '',
      objet_marche: rec.objet || '',
      lien: rec.url_avis || '',
    }
  });
}
return out;

// Extraction simple depuis le corps de l'email d'alerte Malt.
// Ajuster les regex selon le format reel recu (a affiner apres 1er email recu).
const items = $input.all();
const out = [];
for (const item of items) {
  const body = item.json.text || item.json.snippet || '';
  const orgMatch = body.match(/(?:chez|pour)\s+([A-Z][\w\s&-]{2,40})/);
  out.push({
    json: {
      organisation: orgMatch ? orgMatch[1].trim() : 'Mission Malt a qualifier',
      secteur: 'Prive / Autre',
      source: 'malt',
      offre: 'Sprint Outil 30 jours',
      valeur_estimee: null,
      currency: 'EUR',
      contact_name: '',
    }
  });
}
return out;
